#* {{quote-book|gmy|title={{w|Pylos}} Ep 704.5–6|year=c. 1200 {{BC}}|passage={{gmy-table|a={{m|gmy|𐀁𐀪𐀲|tr=-}}𐄁{{m|gmy|𐀂𐀋𐀩𐀊|tr=-}}𐄁{{m|gmy|𐀁𐀐|tr=-}}𐄁{{m|gmy|𐀁𐀄𐀐𐀵|tr=-}}{{m|gmy|𐀤|id=and|tr=-}}𐄁'''{{m|gmy|𐀁𐀵𐀛𐀍|tr=-}}'''𐄁{{m|gmy|𐀁𐀐𐀁|tr=-}}𐄁{{m|gmy|𐀳𐀃|tr=-}}|b={{m|gmy|𐀅𐀗|tr=-}}{{m|gmy|𐀆|id=but|tr=-}}{{m|gmy|𐀖|id=him|tr=-}}𐄁{{m|gmy|𐀞𐀯|id=declare|tr=-}}𐄁{{m|gmy|𐀒𐀵𐀙𐀃|tr=-}}𐄁{{m|gmy|𐀐𐀐𐀕𐀙𐀃|tr=-}}𐄁{{m|gmy|𐀃𐀙𐀵|tr=-}}𐄁{{m|gmy|𐀁𐀐𐀁|tr=-}}}}
|tr={{gmy-table|a=e-ri-ta i-je-re-ja e-ke e-u-ke-to-qe '''e-to-ni-jo''' e-ke-e te-o|b=da-mo-de-mi pa-si ko-to-na-o ke-ke-me-na-o o-na-to e-ke-e}}
